const $=s=>document.querySelector(s),G=window.BundleDuplicateLens,SLUG='bundle-duplicate-lens',NS='amu-web-service-lab',PINGS=[];let result=null,started=false,completed=false;function metric(name){const image=new Image;PINGS.push(image);image.onload=image.onerror=()=>PINGS.splice(PINGS.indexOf(image),1);image.src=`https://api.counterapi.dev/v1/${NS}/${SLUG}-${name}/up?t=${Date.now()}`}metric('view');try{if(!localStorage.getItem(`${SLUG}-counted`))setTimeout(()=>{metric('visitor');localStorage.setItem(`${SLUG}-counted`,'1')},1200)}catch(e){}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),mb=kb=>(kb/1024).toFixed(kb>=10240?1:2);
function render(){const r=result;$('#duplicates').textContent=r.summary.duplicateAssetCount;$('#waste').textContent=mb(r.summary.duplicateKB);$('#rate').textContent=`${r.summary.duplicateRate.toFixed(1)}%`;$('#optimized').textContent=`${mb(r.summary.optimizedKB)} MB`;$('#verdict').textContent=r.status==='clean'?'Bundle間の重複は見つからなかった。':`${r.summary.candidateCount}件が共有化候補。最大候補から依存関係とロード順を確認してね。`;$('#duplicateRows').innerHTML=r.duplicates.length?r.duplicates.map(x=>`<tr><td><b>${esc(x.asset)}</b>${x.sizeMismatch?'<small class="warn">サイズ差あり</small>':''}</td><td>${x.bundles.map(esc).join('<br>')}</td><td>${mb(x.currentKB)} MB</td><td><b>${mb(x.savingsKB)} MB</b></td><td><span class="tag">${x.action}</span></td></tr>`).join(''):'<tr><td colspan="5">重複なし</td></tr>';$('#bundleRows').innerHTML=r.bundles.map(x=>`<div class="bundle"><div><b>${esc(x.bundle)}</b><span>${mb(x.sizeKB)} MB</span></div><i style="width:${x.share}%"></i></div>`).join('');$('#download').disabled=false}
function calculate(){if(!started){metric('start');started=true}try{result=G.analyze(G.parseRows($('#rows').value),{minSavingsKB:$('#threshold').value});render();$('#status').textContent='';if(!completed){metric('complete');completed=true}}catch(error){result=null;$('#status').textContent=error.message;$('#download').disabled=true}}
$('#form').addEventListener('submit',e=>{e.preventDefault();calculate()});$('#sample').onclick=()=>{$('#rows').value='core,Assets/UI/MainAtlas.png,2048\nlevel-forest,Assets/UI/MainAtlas.png,2048\nlevel-city,Assets/UI/MainAtlas.png,2048\nlevel-forest,Assets/Characters/Hero.prefab,3840\nlevel-city,Assets/Characters/Hero.prefab,3840\nlevel-forest,Assets/Audio/Wind.wav,960\nlevel-city,Assets/Audio/Traffic.wav,1240\ncore,Assets/Fonts/Main.ttf,1800';$('#threshold').value=500;calculate()};$('#download').onclick=()=>{if(!result)return;const blob=new Blob([JSON.stringify(G.exportData(result),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bundle-duplicate-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#status').textContent='監査JSONを保存したよ'};calculate();
